function draw(ctx, size) {
  ctx.imageSmoothingEnabled = false;
  const px = (x, y, w, h, c) => { ctx.fillStyle = c; ctx.fillRect(x|0, y|0, w|0, h|0); };
  const O = '#051428', Title = '#000080', Face = '#c0c0c0', FaceLt = '#e8e8e8', FaceDk = '#808080';
  const Red = '#c43c3c', Yellow = '#f4c020', Green = '#208020', Teal = '#008080', Purple = '#800080';
  const Ink = '#0f1419', Paper = '#f0e8d6';

  // crown
  px(18, 2, 28, 10, O);
  px(20, 4, 24, 7, Yellow);
  px(22, 2, 4, 4, Yellow); px(30, 0, 4, 6, Yellow); px(38, 2, 4, 4, Yellow);
  px(24, 5, 16, 2, '#e8a020');
  px(28, 6, 2, 2, Red); px(34, 6, 2, 2, Red);

  // window chrome
  px(6, 12, 52, 48, O);
  px(7, 13, 50, 46, Face);
  px(7, 13, 50, 1, FaceLt);
  px(7, 13, 1, 46, FaceLt);
  px(56, 13, 1, 46, FaceDk);
  px(7, 58, 50, 1, FaceDk);

  // title bar
  px(8, 14, 48, 10, Title);
  px(10, 16, 18, 2, FaceLt);
  px(10, 19, 12, 2, FaceDk);
  // close button
  px(48, 15, 7, 7, Face);
  px(49, 16, 5, 5, Red);
  px(50, 17, 3, 3, FaceLt);

  // client area ads grid
  px(10, 26, 22, 14, Purple);
  px(34, 26, 20, 14, Teal);
  px(10, 42, 22, 12, Green);
  px(34, 42, 20, 12, Red);
  // fake buttons
  px(12, 28, 8, 3, Yellow);
  px(36, 28, 8, 3, Paper);
  px(12, 44, 8, 3, Paper);
  px(36, 44, 8, 3, Yellow);
  // king face peeping center
  px(26, 32, 12, 12, O);
  px(27, 33, 10, 10, Paper);
  px(29, 35, 2, 2, Ink); px(33, 35, 2, 2, Ink);
  px(30, 39, 4, 1, Ink);
  px(31, 40, 2, 1, Red);
}
